package com.jbrempresa.backend.entity;
import java.time.LocalDateTime; import com.fasterxml.jackson.annotation.JsonFormat; import jakarta.persistence.*;
@Entity @Table(name="vias") public class Via {
 @Id @GeneratedValue(strategy=GenerationType.IDENTITY) @Column(name="via_id") private Long viaId; @Column(name="emp_id",nullable=false) private Long empId; @Column(name="cop_id",nullable=false) private Long copId; @Column(name="via_tip",nullable=false,length=30) private String viaTip; @Column(name="via_cod",nullable=false,length=30) private String viaCod; @Column(name="via_nom",nullable=false,length=150) private String viaNom; @Column(name="via_usu_mov",nullable=false,length=50) private String viaUsuMov; @JsonFormat(pattern="dd/MM/yyyy HH:mm:ss") @Column(name="via_fec_mov",nullable=false) private LocalDateTime viaFecMov; @Column(name="via_act",nullable=false) private Boolean viaAct;
 public Long getViaId(){return viaId;} public void setViaId(Long v){viaId=v;} public Long getEmpId(){return empId;} public void setEmpId(Long v){empId=v;} public Long getCopId(){return copId;} public void setCopId(Long v){copId=v;} public String getViaTip(){return viaTip;} public void setViaTip(String v){viaTip=v;} public String getViaCod(){return viaCod;} public void setViaCod(String v){viaCod=v;} public String getViaNom(){return viaNom;} public void setViaNom(String v){viaNom=v;} public String getViaUsuMov(){return viaUsuMov;} public void setViaUsuMov(String v){viaUsuMov=v;} public LocalDateTime getViaFecMov(){return viaFecMov;} public void setViaFecMov(LocalDateTime v){viaFecMov=v;} public Boolean getViaAct(){return viaAct;} public void setViaAct(Boolean v){viaAct=v;}
}
